def letterCombinations(digits):
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    res = []
    cur = []

    def go(i):
        if i == len(digits):
            res.append(cur[:])
            return
        for ch in keys[digits[i]]:
            cur.append(ord(ch) - 96)
            go(i + 1)
            cur.pop()

    go(0)
    return res
